package org.jfree.chart.plot;

import java.awt.Paint;
import java.awt.Stroke;
import java.io.*;
import java.math.*;
import java.util.*;
import org.jfree.chart.event.MarkerChangeEvent;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ValueMarker_equals_TriageGen2Test {

    @Test
    public void testEquals_SameInstance() {
        ValueMarker marker = new ValueMarker(10.0);
        // Covers: if (obj == this) return true;
        assertTrue(marker.equals(marker));
    }

    @Test
    public void testEquals_SuperEqualsFalse() {
        ValueMarker marker1 = new ValueMarker(10.0);
        // We need to trigger !super.equals(obj). 
        // Since ValueMarker extends a class (likely AbstractMarker or similar), 
        // if we pass a different object that fails super.equals, it returns false.
        // In JFreeChart, ValueMarker inherits equals from a parent. 
        // A simple way to fail super.equals is to pass an object of a different type 
        // that is not compatible with the parent's equality logic, 
        // but the code checks super.equals first.
        // However, if we pass null, super.equals(null) is typically false.
        assertFalse(marker1.equals(null));
    }

    @Test
    public void testEquals_NotInstanceOfValueMarker() {
        ValueMarker marker = new ValueMarker(10.0);
        // Covers: if (!(obj instanceof ValueMarker)) return false;
        // We use a different object that might pass super.equals if applicable, 
        // but here we just ensure it's not a ValueMarker.
        assertFalse(marker.equals("Not a ValueMarker"));
    }

    @Test
    public void testEquals_DifferentValue() {
        ValueMarker marker1 = new ValueMarker(10.0);
        ValueMarker marker2 = new ValueMarker(20.0);
        // Covers: if (this.value != that.value) return false;
        // Note: This assumes super.equals(marker2) returns true for different ValueMarkers
        // (which is common if the parent only checks identity or base properties).
        // If super.equals checks value, this test might be caught by the super check.
        // But based on the provided code structure, this is the branch for value comparison.
        assertFalse(marker1.equals(marker2));
    }

    @Test
    public void testEquals_SameValue() {
        ValueMarker marker1 = new ValueMarker(10.0);
        ValueMarker marker2 = new ValueMarker(10.0);
        // Covers: return true; (after all checks pass)
        // We assume super.equals passes for two different instances with same base properties.
        assertTrue(marker1.equals(marker2));
    }
}
